$e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$env=GreenPortalDatabase::env();$pdo=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');$id=max(0,(int)($_GET['id']??0));
