function decodificarOrfao(string $json): mixed { $data=json_decode($json,true); if(is_array($data)&&isset($data['registro_comprimido_base64'])){ $raw=base64_decode((string)$data['registro_comprimido_base64'],true); $expanded=$raw!==false?@gzuncompress($raw):false; if($expanded!==false){$decoded=json_decode($expanded,true);$data['registro_decodificado']=$decoded??$expanded;unset($data['registro_comprimido_base64']);} } return $data??$json; }
